// ── Session Detail ─────────────────────────────────────────────────────────

export function getMockSessionDetail(id: string) {
  const session = MOCK_SESSIONS.find(s => s.id === id);
  if (!session) return null;

  const shots = MOCK_SHOTS.filter(s => s.sessionId === id).map((s, i) => ({
    ...s,
    shotNumber: i + 1,
  }));

  return { ...session, shots, tags: [] };
}
